const t = $json;
let messages = [];
try { messages = JSON.parse(t.messages || '[]'); } catch (e) {}
const body = { model: t.litellm_model, max_tokens: Number(t.max_tokens) || 4000, messages: messages };
body.tools = [{ name: 'web_search', description: 'Wyszukaj w internecie aktualne informacje (ceny, biezace wydarzenia, specyfikacje, swieze fakty). Uzyj, gdy potrzebujesz danych spoza swojej wiedzy. Wykonaj wszystkie potrzebne zapytania w jednej turze, a nastepnie odpowiedz.', input_schema: { type: 'object', properties: { query: { type: 'string', description: 'Zapytanie do wyszukiwarki' } }, required: ['query'] } }];
const temp = t.temperature;
if (temp !== null && temp !== '' && temp !== undefined) { body.temperature = Number(temp); }
return [{ json: { body: body } }];

const trig = $('When Called').first().json;
const resp = $('Call Messages').first().json || {};
const body = resp.body || {};
const headers = resp.headers || {};
const served = (resp.model_used != null && String(resp.model_used).trim() !== '') ? String(resp.model_used).trim() : trig.litellm_model;
const fell_back_round = (resp.fell_back === true || resp.fell_back === 'true');
const usage = body.usage || {};
const inTok = Number(usage.input_tokens || 0);
const outTok = Number(usage.output_tokens || 0);
const ch = (headers['x-litellm-response-cost'] != null && headers['x-litellm-response-cost'] !== '') ? headers['x-litellm-response-cost'] : headers['x-litellm-response-cost-original'];
const usd = (ch != null && ch !== '') ? Number(ch) : 0;
const content = Array.isArray(body.content) ? body.content : [];
let text = '';
const queries = [];
for (const b of content) {
  if (b && b.type === 'text' && b.text) { text += b.text; }
  else if (b && b.type === 'tool_use' && b.name === 'web_search') { queries.push({ tool_use_id: b.id, query: (b.input && b.input.query) || '' }); }
}
const depth = Number(trig.depth || 0);
const maxDepth = Number(trig.max_depth || 5);
const stop = body.stop_reason || '';
const acc_in = Number(trig.acc_in || 0) + inTok;
const acc_out = Number(trig.acc_out || 0) + outTok;
const acc_usd = Number(trig.acc_usd || 0) + usd;
const acc_searches = Number(trig.acc_searches || 0);
const acc_fell_back = (trig.acc_fell_back === true || trig.acc_fell_back === 'true') || fell_back_round;
let prevSources = []; try { prevSources = JSON.parse(trig.sources || '[]'); } catch (e) {}
let prevMessages = []; try { prevMessages = JSON.parse(trig.messages || '[]'); } catch (e) {}
let prevCalls = []; try { prevCalls = JSON.parse(trig.calls || '[]'); } catch (e) {}
prevCalls = prevCalls.concat([{ call_type: 'research_round', model_used: served, input_tokens: inTok, output_tokens: outTok, usd_cost: usd }]);
const needs_search = stop === 'tool_use' && queries.length > 0 && depth < maxDepth;
const capped = stop === 'tool_use' && queries.length > 0 && depth >= maxDepth;
return [{ json: { needs_search: needs_search, capped: capped, text: text, stop: stop, queries: queries, assistant_content: content, depth: depth, maxDepth: maxDepth, acc_in: acc_in, acc_out: acc_out, acc_usd: acc_usd, acc_searches: acc_searches, acc_fell_back: acc_fell_back, prevSources: prevSources, prevMessages: prevMessages, prevCalls: prevCalls, litellm_model: trig.litellm_model, fallback_model: trig.fallback_model, max_tokens: trig.max_tokens, temperature: trig.temperature, tavily_max_results: trig.tavily_max_results, clickup_task_id: trig.clickup_task_id, caller_user_id: trig.caller_user_id, process_type: trig.process_type, triggered_by: trig.triggered_by, invocation_type: trig.invocation_type, impact: trig.impact } }];

const pt = $('Parse Turn').first().json;
const emits = $('Emit Queries').all();
const searches = $input.all();
const NL = String.fromCharCode(10);
const toolResults = [];
const newSources = (pt.prevSources || []).slice();
const seen = {};
for (const s of newSources) { if (s && s.url) seen[s.url] = true; }
const searchCalls = [];
let searchUsd = 0;
for (let i = 0; i < emits.length; i++) {
  const tuid = emits[i].json.tool_use_id;
  let results = [];
  let scost = 0;
  try {
    const it = (searches[i] && searches[i].json) ? searches[i].json : {};
    const bodyR = it.body || it;
    results = (bodyR && bodyR.results) || [];
    const hh = it.headers || {};
    const hc = (hh['x-litellm-response-cost'] != null && hh['x-litellm-response-cost'] !== '') ? hh['x-litellm-response-cost'] : hh['x-litellm-response-cost-original'];
    if (hc != null && hc !== '') scost = Number(hc);
  } catch (e) {}
  let txt = '';
  for (const r of results) {
    txt += '- ' + (r.title || '') + ' (' + (r.url || '') + ')' + NL + (r.snippet || '') + NL + NL;
    if (r && r.url && !seen[r.url]) { seen[r.url] = true; newSources.push({ url: r.url, title: r.title || r.url }); }
  }
  if (!txt) { txt = 'Brak wynikow.'; }
  toolResults.push({ type: 'tool_result', tool_use_id: tuid, content: txt });
  searchCalls.push({ call_type: 'web_search', model_used: 'tavily', input_tokens: 0, output_tokens: 0, usd_cost: scost });
  searchUsd += scost;
}
const messages2 = (pt.prevMessages || []).slice();
messages2.push({ role: 'assistant', content: pt.assistant_content });
messages2.push({ role: 'user', content: toolResults });
const newCalls = (pt.prevCalls || []).concat(searchCalls);
return [{ json: { litellm_model: pt.litellm_model, messages: JSON.stringify(messages2), max_tokens: pt.max_tokens, temperature: pt.temperature, tavily_max_results: pt.tavily_max_results, depth: (pt.depth || 0) + 1, max_depth: pt.maxDepth, acc_in: pt.acc_in, acc_out: pt.acc_out, acc_usd: (Number(pt.acc_usd || 0) + searchUsd), acc_searches: (pt.acc_searches || 0) + emits.length, sources: JSON.stringify(newSources), calls: JSON.stringify(newCalls), clickup_task_id: pt.clickup_task_id, caller_user_id: pt.caller_user_id, process_type: pt.process_type, triggered_by: pt.triggered_by, invocation_type: pt.invocation_type, impact: pt.impact, fallback_model: pt.fallback_model, acc_fell_back: pt.acc_fell_back } }];

const j = $json;
const NL = String.fromCharCode(10);
let completion = j.text || '';
let web_search_error = false;
let web_search_error_code = '';
const srcs = j.prevSources || [];
if (!completion) {
  if (j.capped) { web_search_error = true; web_search_error_code = 'max_rounds_reached'; completion = 'Agent wykonal maksymalna liczbe rund wyszukiwania, ale nie sformulowal pelnej odpowiedzi. Zawez pytanie lub popros o ponowna probe.'; }
  else if (j.acc_searches > 0 || srcs.length) { web_search_error = true; web_search_error_code = 'no_final_text'; completion = 'Wyszukiwanie zakonczone, ale model nie zwrocil odpowiedzi tekstowej.'; }
  if (srcs.length) { completion += NL + NL + 'Znalezione zrodla:' + NL + srcs.map(function (s, i) { return (i + 1) + '. [' + (s.title || s.url) + '](' + s.url + ')'; }).join(NL); }
}
return [{ json: { completion: completion, sources: srcs, web_search_used: (j.acc_searches > 0) || (srcs.length > 0), web_search_error: web_search_error, web_search_error_code: web_search_error_code, input_tokens: j.acc_in, output_tokens: j.acc_out, usd_cost: j.acc_usd, searches: j.acc_searches, rounds: j.depth, fell_back: (j.acc_fell_back === true || j.acc_fell_back === 'true'), calls: (j.prevCalls || []) } }];

const bf = $('Build Final').first().json;
const ctx = $('When Called').first().json;
const calls = Array.isArray(bf.calls) ? bf.calls : [];
if (!calls.length) { return [{ json: { __noop: true } }]; }
return calls.map(function (c) { return { json: {
  clickup_task_id: ctx.clickup_task_id || null,
  caller_user_id: ctx.caller_user_id || null,
  process_type: ctx.process_type || null,
  triggered_by: 'search_step',
  invocation_type: ctx.invocation_type || 'explicit',
  impact: ctx.impact || null,
  model_used: c.model_used || null,
  input_tokens: (c.input_tokens != null) ? c.input_tokens : null,
  output_tokens: (c.output_tokens != null) ? c.output_tokens : null,
  usd_cost: (c.usd_cost != null) ? c.usd_cost : null
} }; });
